using System.ClientModel;
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using OpenAI;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// Build the IChatClient through the MEAI abstraction
IChatClient chatClient = new OpenAIClient(new ApiKeyCredential(apiKey))
    .GetChatClient(modelId)
    .AsIChatClient();

// Create the research tools
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearcher.SearchWeb),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// Build the agent with tools and a system prompt
var agent = new ChatClientAgent(chatClient,
    """
    You are a research assistant. Your job is to research a topic thoroughly,
    then provide a well-organized summary.

    Workflow:
    1. Break the topic into 2-3 key sub-questions.
    2. Use the SearchWeb tool to find information for each sub-question.
    3. Use the AddNote tool to record important facts and source URLs.
    4. After gathering enough information, use GetNotes to review your notes.
    5. Provide a final summary with key findings and sources.

    Always cite your sources. Be thorough but concise.
    """,
    tools);

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
};

Console.WriteLine("=== Research Agent ===");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();
if (string.IsNullOrEmpty(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a summary: {topic}"),
};

await foreach (var update in agent.InvokeStreamingAsync(history, options))
{
    Console.Write(update.Text);
}

Console.WriteLine("\n\n=== Research Complete ===");

