using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.RegularExpressions;

/// <summary>
/// Provides a web search tool that fetches and extracts text from search result pages.
/// </summary>
public sealed partial class WebSearcher : IDisposable
{
    private readonly HttpClient _http = new()
    {
        Timeout = TimeSpan.FromSeconds(15),
        DefaultRequestHeaders =
        {
            { "User-Agent", "ResearchAgent/1.0" },
            { "Accept", "text/html" },
        },
    };

    [Description("Search the web for information on a query. Returns text snippets from search results.")]
    public async Task<string> SearchWeb(
        [Description("The search query string")] string query)
    {
        try
        {
            // Use DuckDuckGo HTML search (no API key required)
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";

            var html = await _http.GetStringAsync(url);

            return ParseSearchResults(html, maxResults: 5);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static string ParseSearchResults(string html, int maxResults)
    {
        var sb = new StringBuilder();
        var resultMatches = ResultPattern().Matches(html);
        var snippetMatches = SnippetPattern().Matches(html);

        var count = Math.Min(resultMatches.Count, Math.Min(snippetMatches.Count, maxResults));
        if (count == 0)
        {
            return "No search results found.";
        }

        for (var i = 0; i < count; i++)
        {
            var title = StripHtml(WebUtility.HtmlDecode(resultMatches[i].Groups[1].Value));
            var snippet = StripHtml(WebUtility.HtmlDecode(snippetMatches[i].Groups[1].Value));

            sb.AppendLine($"Result {i + 1}: {title}");
            sb.AppendLine($"  {snippet}");
            sb.AppendLine();
        }

        return sb.ToString();
    }

    private static string StripHtml(string input)
        => HtmlTagPattern().Replace(input, "").Trim();

    [GeneratedRegex(@"<a[^>]+class=""result__a""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex ResultPattern();

    [GeneratedRegex(@"<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>", RegexOptions.Singleline)]
    private static partial Regex SnippetPattern();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex HtmlTagPattern();

    public void Dispose() => _http.Dispose();
}

using System.ComponentModel;
using System.Text;

/// <summary>
/// Provides note-taking tools for the research agent to record and review findings.
/// </summary>
public sealed class Notebook
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a fact or finding. Use this to record important information discovered during research.")]
    public string AddNote(
        [Description("The topic or category for this note")] string topic,
        [Description("The content of the note — a fact, finding, or observation")] string content,
        [Description("The source URL or reference, if available")] string? source = null)
    {
        var note = new Note(topic, content, source);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved under topic '{topic}'.";
    }

    [Description("Retrieve all saved research notes, organized by topic.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");

        var grouped = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase);
        foreach (var group in grouped)
        {
            sb.AppendLine($"## {group.Key}");
            foreach (var note in group)
            {
                sb.AppendLine($"  - {note.Content}");
                if (!string.IsNullOrEmpty(note.Source))
                {
                    sb.AppendLine($"    Source: {note.Source}");
                }
            }

            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed record Note(string Topic, string Content, string? Source);
}

