using System.ComponentModel;
using System.Text;

/// <summary>
/// Provides note-taking tools for the research agent to record and review findings.
/// </summary>
public sealed class Notebook
{
    private readonly List<Note> _notes = [];

    [Description("Save a research note with a fact or finding. Use this to record important information discovered during research.")]
    public string AddNote(
        [Description("The topic or category for this note")] string topic,
        [Description("The content of the note — a fact, finding, or observation")] string content,
        [Description("The source URL or reference, if available")] string? source = null)
    {
        var note = new Note(topic, content, source);
        _notes.Add(note);
        return $"Note #{_notes.Count} saved under topic '{topic}'.";
    }

    [Description("Retrieve all saved research notes, organized by topic.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been saved yet.";
        }

        var sb = new StringBuilder();
        sb.AppendLine($"=== Research Notes ({_notes.Count} total) ===\n");

        var grouped = _notes.GroupBy(n => n.Topic, StringComparer.OrdinalIgnoreCase);
        foreach (var group in grouped)
        {
            sb.AppendLine($"## {group.Key}");
            foreach (var note in group)
            {
                sb.AppendLine($"  - {note.Content}");
                if (!string.IsNullOrEmpty(note.Source))
                {
                    sb.AppendLine($"    Source: {note.Source}");
                }
            }

            sb.AppendLine();
        }

        return sb.ToString();
    }

    private sealed record Note(string Topic, string Content, string? Source);
}

